/// RealtimeError wraps realtime-specific error variants.
#[derive(Debug)]
pub enum RealtimeError {
    Connect(Error),
    Send(Error),
    Recv(Error),
    Closed,
    NotImplemented(String),
}

impl std::fmt::Display for RealtimeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RealtimeError::Connect(e) => write!(f, "connect error: {e}"),
            RealtimeError::Send(e) => write!(f, "send error: {e}"),
            RealtimeError::Recv(e) => write!(f, "recv error: {e}"),
            RealtimeError::Closed => write!(f, "connection closed"),
            RealtimeError::NotImplemented(s) => write!(f, "not implemented: {s}"),
        }
    }
}

