/// LongpollTransport opens a long-poll GET loop using reqwest.
#[derive(Debug, Default)]
pub struct LongpollTransport {
    pub http_client: Option<reqwest::Client>,
}

/// LongpollConn is the live longpoll connection returned by [`LongpollTransport::connect`].
pub struct LongpollConn {
    state: LongpollState,
}

#[async_trait::async_trait]
impl Transport for LongpollTransport {
    fn name(&self) -> &'static str {
        "longpoll"
    }
    fn kind(&self) -> TransportKind {
        TransportKind::Longpoll
    }
    async fn connect(
        &self,
        url: &str,
        opts: &TransportOpts,
    ) -> Result<Box<dyn TransportConn>, RealtimeError> {
        let client = self
            .http_client
            .clone()
            .or_else(|| opts.http_client.clone())
            .unwrap_or_else(reqwest::Client::new);
        let state = LongpollState {
            client,
            url: url.to_string(),
            cursor: None,
            pending_events: VecDeque::new(),
            headers: opts.headers.clone(),
            max_reconnect_attempts: opts.max_reconnect_attempts.unwrap_or(5),
            reconnect_delay_ms: opts.reconnect_delay_ms.unwrap_or(1000),
            reconnect_attempts: 0,
        };
        Ok(Box::new(LongpollConn { state }))
    }
}

#[async_trait::async_trait]
impl TransportConn for LongpollConn {
    fn kind(&self) -> TransportKind {
        TransportKind::Longpoll
    }
    async fn send_json(&mut self, value: serde_json::Value) -> Result<(), RealtimeError> {
        self.state
            .client
            .post(self.state.url.as_str())
            .json(&value)
            .send()
            .await
            .map_err(|e| RealtimeError::Send(Error::Other(e.to_string())))?;
        Ok(())
    }
    async fn recv_json(&mut self) -> Result<serde_json::Value, RealtimeError> {
        loop {
            if let Some(ev) = self.state.pending_events.pop_front() {
                return Ok(ev);
            }
            let request_url = match &self.state.cursor {
                Some(c) => format!("{}?cursor={}", self.state.url, c),
                None => self.state.url.clone(),
            };
            let mut req = self.state.client.get(request_url.as_str());
            for (k, v) in &self.state.headers {
                req = req.header(k.as_str(), v.as_str());
            }
            match req.send().await {
                Err(e) => {
                    self.state.reconnect_attempts += 1;
                    if self.state.reconnect_attempts >= self.state.max_reconnect_attempts {
                        return Err(RealtimeError::Recv(Error::Other(e.to_string())));
                    }
                    tokio::time::sleep(tokio::time::Duration::from_millis(
                        self.state.reconnect_delay_ms,
                    ))
                    .await;
                }
                Ok(resp) => {
                    let bytes = resp
                        .bytes()
                        .await
                        .map_err(|e| RealtimeError::Recv(Error::Other(e.to_string())))?;

                    #[derive(serde::Deserialize)]
                    struct PollResponse {
                        #[serde(default)]
                        events: Vec<serde_json::Value>,
                        cursor: Option<String>,
                    }

                    let parsed: PollResponse = serde_json::from_slice(&bytes)
                        .map_err(|e| RealtimeError::Recv(Error::Json(e)))?;
                    self.state.cursor = parsed.cursor;
                    for ev in parsed.events {
                        self.state.pending_events.push_back(ev);
                    }
                }
            }
        }
    }
    async fn close(&mut self) -> Result<(), RealtimeError> {
        /* no persistent connection to tear down */
        Ok(())
    }
}

