/// ResumableConnection is a typed, self-reconnecting realtime channel.
/// Send/Recv type parameters encode the message types flowing in each direction.
pub struct ResumableConnection<Send, Recv> {
    state: ConnectionState,
    url: String,
    opts: ResumableConnectionOpts,
    transport_opts: TransportOpts,
    transports: Vec<Box<dyn Transport>>,
    conn: Option<Box<dyn TransportConn>>,
    proven_index: Option<usize>,
    reconnect_attempts: u32,
    _send: PhantomData<Send>,
    _recv: PhantomData<Recv>,
}

impl<SendMsg, RecvMsg> ResumableConnection<SendMsg, RecvMsg>
where
    SendMsg: Serialize,
    RecvMsg: DeserializeOwned,
{
    /// connect tries each transport in order, memoizes the first that succeeds,
    /// and returns the active ResumableConnection.
    pub async fn connect(
        url: String,
        opts: ResumableConnectionOpts,
        transports: Vec<Box<dyn Transport>>,
    ) -> Result<Self, RealtimeError> {
        if transports.is_empty() {
            return Err(RealtimeError::Connect(Error::Other(
                "no transports configured".into(),
            )));
        }
        let transport_opts = TransportOpts {
            reconnect_token: opts.reconnect_token.clone(),
            protocols: opts.protocols.clone(),
            last_event_id: opts.last_event_id.clone(),
            headers: opts.headers.clone(),
            http_client: None,
            max_reconnect_attempts: opts.max_reconnect_attempts,
            reconnect_delay_ms: opts.reconnect_delay_ms,
        };
        let mut rc = ResumableConnection {
            state: ConnectionState::Connecting,
            url,
            opts,
            transport_opts,
            transports,
            conn: None,
            proven_index: None,
            reconnect_attempts: 0,
            _send: PhantomData,
            _recv: PhantomData,
        };
        rc.open_chain().await?;
        Ok(rc)
    }

    /// connect_with_defaults builds the canonical transport chain
    /// `[WsTransport, SseTransport, LongpollTransport]` and calls [`Self::connect`].
    /// Convenience entry point for consumers that don't need a custom chain.
    pub async fn connect_with_defaults(
        url: String,
        opts: ResumableConnectionOpts,
    ) -> Result<Self, RealtimeError> {
        let transports: Vec<Box<dyn Transport>> = vec![
            Box::new(WsTransport),
            Box::new(SseTransport::default()),
            Box::new(LongpollTransport::default()),
        ];
        Self::connect(url, opts, transports).await
    }

    /// state returns the current connection lifecycle state.
    pub fn state(&self) -> &ConnectionState {
        &self.state
    }

    /// proven_transport returns the kind of the last successfully-opened transport.
    pub fn proven_transport(&self) -> Option<TransportKind> {
        self.proven_index
            .and_then(|i| self.transports.get(i))
            .map(|t| t.kind())
    }

    /// current_transport returns the kind of the currently-active transport.
    pub fn current_transport(&self) -> Option<TransportKind> {
        self.conn.as_ref().map(|c| c.kind())
    }

    /// send serialises a message and writes it to the active transport.
    pub async fn send(&mut self, data: &SendMsg) -> Result<(), RealtimeError> {
        let conn = self.conn.as_mut().ok_or(RealtimeError::Closed)?;
        let v = serde_json::to_value(data).map_err(|e| RealtimeError::Send(Error::Json(e)))?;
        conn.send_json(v).await
    }

    /// recv reads the next message from the transport and deserialises it.
    /// On transport failure: invalidates `proven_index`, sleeps `reconnect_delay_ms`,
    /// re-runs `open_chain()` (full fallback sequence). Mirrors Python `_iter`
    /// and TS `createResumableConnection`'s recv loop. Gives up after
    /// `max_reconnect_attempts` attempts and returns the last error.
    pub async fn recv(&mut self) -> Result<RecvMsg, RealtimeError> {
        let max_attempts = self.opts.max_reconnect_attempts.unwrap_or(5);
        let delay_ms = self.opts.reconnect_delay_ms.unwrap_or(1000);
        loop {
            let result = {
                let conn = self.conn.as_mut().ok_or(RealtimeError::Closed)?;
                conn.recv_json().await
            };
            match result {
                Ok(v) => {
                    self.reconnect_attempts = 0;
                    return serde_json::from_value(v)
                        .map_err(|e| RealtimeError::Recv(Error::Json(e)));
                }
                Err(err) => {
                    self.reconnect_attempts += 1;
                    if max_attempts > 0 && self.reconnect_attempts > max_attempts {
                        self.state = ConnectionState::Disconnected;
                        return Err(err);
                    }
                    self.state = ConnectionState::Reconnecting;
                    /* drop the dead conn + invalidate proven so chain retries from the top */
                    if let Some(mut c) = self.conn.take() {
                        let _ = c.close().await;
                    }
                    self.proven_index = None;
                    if delay_ms > 0 {
                        tokio::time::sleep(tokio::time::Duration::from_millis(delay_ms)).await;
                    }
                    if let Err(open_err) = self.open_chain().await {
                        self.state = ConnectionState::Disconnected;
                        return Err(open_err);
                    }
                }
            }
        }
    }

    /// close gracefully shuts down the connection.
    pub async fn close(&mut self) -> Result<(), RealtimeError> {
        if let Some(mut c) = self.conn.take() {
            let _ = c.close().await;
        }
        self.state = ConnectionState::Disconnected;
        Ok(())
    }

    async fn open_chain(&mut self) -> Result<(), RealtimeError> {
        /* Try proven first if set */
        if let Some(i) = self.proven_index {
            if let Some(t) = self.transports.get(i) {
                if let Ok(c) = t.connect(&self.url, &self.transport_opts).await {
                    self.conn = Some(c);
                    self.state = ConnectionState::Connected;
                    return Ok(());
                }
            }
        }
        /* Full chain */
        let mut last_err: Option<RealtimeError> = None;
        for (i, t) in self.transports.iter().enumerate() {
            match t.connect(&self.url, &self.transport_opts).await {
                Ok(c) => {
                    self.conn = Some(c);
                    self.proven_index = Some(i);
                    self.state = ConnectionState::Connected;
                    return Ok(());
                }
                Err(e) => last_err = Some(e),
            }
        }
        Err(last_err.unwrap_or(RealtimeError::Connect(Error::Other(
            "all transports failed".into(),
        ))))
    }

}

async fn build_sse_state(
    url: String,
    http_client: reqwest::Client,
    opts: &TransportOpts,
) -> Result<SseState, reqwest::Error> {
    let mut req_builder = http_client
        .get(url.as_str())
        .header("Accept", "text/event-stream");
    if let Some(ref last_event_id) = opts.last_event_id {
        req_builder = req_builder.header("Last-Event-ID", last_event_id.as_str());
    }
    for (k, v) in &opts.headers {
        req_builder = req_builder.header(k.as_str(), v.as_str());
    }
    let resp = req_builder.send().await?;
    let reconnect_delay_ms = opts.reconnect_delay_ms.unwrap_or(1000);
    let max_reconnect_attempts = opts.max_reconnect_attempts.unwrap_or(5);
    let last_event_id = opts.last_event_id.clone();
    let extra_headers = opts.headers.clone();
    let byte_stream: ByteStream = Box::pin(resp.bytes_stream());
    Ok(SseState {
        byte_stream,
        buf: Vec::new(),
        last_event_id,
        retry_hint_ms: reconnect_delay_ms,
        http_client,
        url,
        extra_headers,
        max_reconnect_attempts,
        reconnect_delay_ms,
        reconnect_attempts: 0,
    })
}
